    public static readonly string[] Keys = ["SkyArt", "SunArt", "FarArt", "NearArt", "SideArt"];

    /// <summary>The geometries of a theme's scene, by resource key (empty for themes without one).</summary>
    public static IEnumerable<(string Key, Geometry Geometry)> For(string? theme)
    {
        if (theme is null || !Scenes.TryGetValue(theme, out var s)) yield break;
        yield return ("SkyArt", Geometry.Parse(s.Sky));
        yield return ("SunArt", Geometry.Parse(s.Sun));
        yield return ("FarArt", Geometry.Parse(s.Far));
        yield return ("NearArt", Geometry.Parse(s.Near));
        yield return ("SideArt", Geometry.Parse(s.Side));
    }
}
